const html = $json.output || "";

// Extract <title>
const title = html.match(/<title[^>]*>([^<]*)<\/title>/i)?.[1]?.trim() || null;

// Extract meta description
const metaDescription = html.match(/<meta\s+name=["']description["'][^>]*content=["']([^"']+)["']/i)?.[1]?.trim() || null;

// Extract all <h1> headings
const h1s = [...html.matchAll(/<h1[^>]*>(.*?)<\/h1>/gi)].map(m => m[1].trim()).join(" ");
const h2s = [...html.matchAll(/<h2[^>]*>(.*?)<\/h2>/gi)].map(m => m[1].trim()).join(" ");

return   {
    json: {
      title,
      metaDescription,
      h1s,
      h2s
    }
  }
;

